class Solution {
public:
    int countNodes(TreeNode* root) {
        if (!root) return 0;
        int leftDepth = 0, rightDepth = 0;
        TreeNode* curr = root;
        while (curr) { leftDepth++; curr = curr->left; }
        curr = root;
        while (curr) { rightDepth++; curr = curr->right; }
        if (leftDepth == rightDepth) return (1 << leftDepth) - 1;
        return 1 + countNodes(root->left) + countNodes(root->right);
    }
};

class Solution {
    public int countNodes(TreeNode root) {
        if (root == null) return 0;
        int leftDepth = 0, rightDepth = 0;
        TreeNode curr = root;
        while (curr != null) { leftDepth++; curr = curr.left; }
        curr = root;
        while (curr != null) { rightDepth++; curr = curr.right; }
        if (leftDepth == rightDepth) return (1 << leftDepth) - 1;
        return 1 + countNodes(root.left) + countNodes(root.right);
    }
}

var countNodes = function(root) {
    if (!root) return 0;
    let leftDepth = 0, rightDepth = 0;
    let curr = root;
    while (curr) { leftDepth++; curr = curr.left; }
    curr = root;
    while (curr) { rightDepth++; curr = curr.right; }
    if (leftDepth === rightDepth) return (1 << leftDepth) - 1;
    return 1 + countNodes(root.left) + countNodes(root.right);
};
